    ['Is the venue accessible?','Yes. The Old Gallery offers a step-free entrance, lifts to all floors, accessible restrooms and quiet seating areas. Contact us in advance for a personal host.'],
    ['Can I change my ticket tier?','Yes. Tiers can be upgraded up to 24 hours before the event, subject to availability. Downgrades are not possible in this demo.'],
    ['How do I save the event to my calendar?','Press any "Save to Calendar" button on this page. A file called artifact-museum-night.ics will download; open it to add the event to Apple Calendar, Google Calendar or Outlook.']
  ];

  /* ---------- Image with fallbacks ---------- */
  function fallback(img,key){
    var step=0;
    img.addEventListener('error',function(){
      step++;
      if(step===1){img.src='https://picsum.photos/seed/'+encodeURIComponent(key)+'/1200/900'}
      else{img.removeAttribute('src');img.style.opacity=0}
    });
  }
  var heroImg=$('.hero-bg img');fallback(heroImg,'museum-night-hero');

  /* ---------- Render ---------- */
  $('#timeline').innerHTML=program.map(function(p,i){
    return '<li class="t-item reveal" style="--d:'+(i%3)*.06+'s"><div class="t-time">'+p[0]+'</div><div class="t-card glass"><h3>'+esc(p[1])+'</h3><p>'+esc(p[2])+'</p><span class="tag">'+esc(p[3])+'</span></div></li>';
  }).join('');

  var grid=$('#artistGrid');
  grid.innerHTML=artists.map(function(a,i){
    var k=IMG[i%IMG.length];
    return '<article class="a-card reveal" style="--d:'+(i%4)*.08+'s"><div class="img-box"><img loading="lazy" src="https://source.unsplash.com/featured/1200x900?'+k+'" data-key="artist'+i+'" alt="Portrait-style artwork for '+esc(a[0])+'"></div><div class="a-body"><span class="role">'+esc(a[1])+'</span><h3>'+esc(a[0])+'</h3><p>'+esc(a[2])+'</p><button class="btn small" type="button" data-artist="'+i+'" aria-label="View details for '+esc(a[0])+'">View details</button></div></article>';
  }).join('');
  $$('img[data-key]',grid).forEach(function(im){fallback(im,im.dataset.key)});

  $('#faqList').innerHTML=faqs.map(function(f,i){
    return '<div class="faq-item reveal"><h3 style="font-size:inherit"><button class="faq-q" type="button" aria-expanded="false" aria-controls="fa'+i+'" id="fq'+i+'"><span>'+esc(f[0])+'</span><i aria-hidden="true"></i></button></h3><div class="faq-a" id="fa'+i+'" role="region" aria-labelledby="fq'+i+'"><div><p>'+esc(f[1])+'</p></div></div></div>';
  }).join('');
  $$('.faq-q').forEach(function(b){
    b.addEventListener('click',function(){
      var item=b.closest('.faq-item'),open=!item.classList.contains('open');
      item.classList.toggle('open',open);b.setAttribute('aria-expanded',open);
    });
  });

  /* ---------- Toast ---------- */
  function toast(msg){
    var t=document.createElement('div');t.className='toast';t.textContent=msg;
    $('#toasts').appendChild(t);
    setTimeout(function(){t.classList.add('out');setTimeout(function(){t.remove()},400)},4200);
  }

  /* ---------- Nav ---------- */
  var nav=$('#nav'),burger=$('#burger'),links=$('#links');
  function onScroll(){nav.classList.toggle('scrolled',window.scrollY>30)}
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
  function setMenu(o){links.classList.toggle('open',o);burger.setAttribute('aria-expanded',o)}
  burger.addEventListener('click',function(){setMenu(!links.classList.contains('open'))});
  $$('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var id=a.getAttribute('href');
      if(a.hasAttribute('data-noop')){e.preventDefault();toast('Demo link — nothing to see here yet.');return}
      var t=id.length>1?$(id):null;
      if(id==='#top'){e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});setMenu(false);return}
      if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth',block:'start'});setMenu(false);
        if(history.replaceState){try{history.replaceState(null,'',id)}catch(_){}}}
    });
  });
  // active link
  var navLinks=$$('.links a.lnk');
  var secs=navLinks.map(function(a){return $(a.getAttribute('href'))});
  function setActive(){
    var y=window.scrollY+nav.offsetHeight+window.innerHeight*.25,cur=-1;
    secs.forEach(function(s,i){if(s&&s.offsetTop<=y)cur=i});
    // past FAQ: newsletter/footer shouldn't keep FAQ active
    var faqS=$('#faq');if(cur===secs.length-1&&faqS&&window.scrollY+nav.offsetHeight>faqS.offsetTop+faqS.offsetHeight)cur=-1;
    navLinks.forEach(function(a,i){var on=i===cur;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current')});
  }
  window.addEventListener('scroll',setActive,{passive:true});window.addEventListener('resize',setActive);setActive();

  /* ---------- Reveal ---------- */
  var mapEl=$('#map');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12,rootMargin:'0px 0px -40px 0px'});
    $$('.reveal').forEach(function(el){io.observe(el)});
  }else{$$('.reveal').forEach(function(el){el.classList.add('in')});mapEl.classList.add('in')}
  mapEl.classList.add('in-wait');
  if('IntersectionObserver' in window){new IntersectionObserver(function(es,o){if(es[0].isIntersecting){mapEl.classList.add('in');o.disconnect()}},{threshold:.3}).observe(mapEl)}

  /* ---------- Modals ---------- */
  var lastFocus=null,openOverlay=null;
  var FOCUS='a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])';
  function openModal(ov){
    lastFocus=document.activeElement;openOverlay=ov;
    ov.classList.add('show');ov.setAttribute('aria-hidden','false');
    document.body.classList.add('locked');
    requestAnimationFrame(function(){ov.classList.add('vis')});
    var f=$('[data-close]',ov);setTimeout(function(){var first=$('input,button:not([data-close])',$('form',ov)||ov)||f;(ov.id==='artistOverlay'?f:first).focus()},50);
  }
  function closeModal(){
    var ov=openOverlay;if(!ov)return;
    ov.classList.remove('vis');ov.setAttribute('aria-hidden','true');openOverlay=null;
    setTimeout(function(){ov.classList.remove('show')},300);
    document.body.classList.remove('locked');
    if(lastFocus&&lastFocus.focus)lastFocus.focus();
  }
  $$('.overlay').forEach(function(ov){
    ov.addEventListener('mousedown',function(e){if(e.target===ov)closeModal()});
    $$('[data-close]',ov).forEach(function(b){b.addEventListener('click',closeModal)});
  });
  document.addEventListener('keydown',function(e){
    if(!openOverlay)return;
    if(e.key==='Escape'){e.preventDefault();closeModal();return}
    if(e.key==='Tab'){
      var f=$$(FOCUS,openOverlay).filter(function(x){return x.offsetParent!==null});
      if(!f.length)return;var a=f[0],z=f[f.length-1];
      if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}
      else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}
    }
  });

  // Artist modal
  var amImg=$('#amImg');fallback(amImg,'artist-modal');
  grid.addEventListener('click',function(e){
    var b=e.target.closest('[data-artist]');if(!b)return;
    var i=+b.dataset.artist,a=artists[i];
    amImg.style.opacity=1;amImg.src=$$('img',grid)[i].currentSrc||$$('img',grid)[i].src||'https://picsum.photos/seed/artist'+i+'/1200/900';
    amImg.alt='Artwork associated with '+a[0];
    $('#amName').textContent=a[0];$('#amRole').textContent=a[1];$('#amBio').textContent=a[3];$('#amSession').textContent='Session: '+a[4];
    openModal($('#artistOverlay'));
  });

  // Ticket modal
  var tier=1,qtyIn=$('#tQty');
  function money(n){return '€'+n}
  function updateTotal(){
    var q=parseInt(qtyIn.value,10);if(isNaN(q)||q<1)q=0;if(q>10)q=10;
    $('#tmTotal').textContent=money(tiers[tier].p*q);
  }
  function setErr(input,errId,msg){
    $('#'+errId).textContent=msg||'';
    if(input){if(msg)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid')}
  }
  $$('[data-tier]').forEach(function(b){
    b.addEventListener('click',function(){
      tier=+b.dataset.tier;
      $('#tmTier').textContent=tiers[tier].n;$('#tmUnit').textContent=money(tiers[tier].p)+' / ticket';
      $('#tmForm').hidden=false;$('#tmSuccess').hidden=true;
      $('#ticketForm').reset();qtyIn.value=1;
      ['tName','tEmail','tQty'].forEach(function(id){setErr($('#'+id),id+'E','')});setErr(null,'tTermsE','');
      updateTotal();openModal($('#ticketOverlay'));
    });
  });
  $('#qMinus').addEventListener('click',function(){qtyIn.value=Math.max(1,(parseInt(qtyIn.value,10)||1)-1);updateTotal()});
  $('#qPlus').addEventListener('click',function(){qtyIn.value=Math.min(10,(parseInt(qtyIn.value,10)||0)+1);updateTotal()});
  qtyIn.addEventListener('input',updateTotal);
  var emailRe=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  $('#ticketForm').addEventListener('submit',function(e){
    e.preventDefault();
    var n=$('#tName'),m=$('#tEmail'),q=parseInt(qtyIn.value,10),t=$('#tTerms'),ok=true,first=null;
    function bad(el){ok=false;if(!first)first=el}
    if(n.value.trim().length<2){setErr(n,'tNameE','Please enter the attendee name.');bad(n)}else setErr(n,'tNameE');
    if(!emailRe.test(m.value.trim())){setErr(m,'tEmailE','Please enter a valid email address.');bad(m)}else setErr(m,'tEmailE');
    if(isNaN(q)||q<1||q>10){setErr(qtyIn,'tQtyE','Choose between 1 and 10 tickets.');bad(qtyIn)}else setErr(qtyIn,'tQtyE');
    if(!t.checked){setErr(null,'tTermsE','You must accept the terms to continue.');bad(t)}else setErr(null,'tTermsE');
    if(!ok){first.focus();return}
    $('#tmForm').hidden=true;$('#tmSuccess').hidden=false;
    $('#tmSuccessText').textContent=q+' × '+tiers[tier].n+' reserved for '+n.value.trim()+' — total '+money(tiers[tier].p*q)+'. A demo confirmation would be sent to '+m.value.trim()+'.';
    toast('Reservation confirmed — see you after dark!');
    $('#tmSuccess .btn.primary').focus();
  });

  // Newsletter
  $('#newsForm').addEventListener('submit',function(e){
    e.preventDefault();
    var i=$('#newsEmail'),v=i.value.trim();
    if(!v){setErr(i,'newsErr','Please enter your email address.');i.focus();return}
    if(!emailRe.test(v)){setErr(i,'newsErr','That email address doesn\'t look right.');i.focus();return}
    setErr(i,'newsErr');i.value='';toast('Thank you — you\'re on the list.');
  });
  $('#newsEmail').addEventListener('input',function(){if(this.getAttribute('aria-invalid'))setErr(this,'newsErr')});
  ['tName','tEmail'].forEach(function(id){$('#'+id).addEventListener('input',function(){setErr(this,id+'E')})});
  $('#tTerms').addEventListener('change',function(){setErr(null,'tTermsE')});

  /* ---------- ICS ---------- */
  function ics(){
    var now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');
    var lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ARTIFACT//Museum Night//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH','BEGIN:VEVENT',
      'UID:artifact-museum-night-20261018@artifact.example','DTSTAMP:'+now,
      'DTSTART:20261018T190000','DTEND:20261019T020000',
      'SUMMARY:ARTIFACT: Museum Night','LOCATION:The Old Gallery\\, Warsaw',
      'DESCRIPTION:A cinematic after-hours museum event with exhibitions\\, performances\\, talks\\, and guided tours.',
      'END:VEVENT','END:VCALENDAR'];
    var blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});
    var url=URL.createObjectURL(blob),a=document.createElement('a');
    a.href=url;a.download='artifact-museum-night.ics';a.style.display='none';
    document.body.appendChild(a);a.click();
    setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},1000);
    toast('Calendar file downloaded — open it to add the event.');
  }
  $$('[data-ics]').forEach(function(b){b.addEventListener('click',ics)});
})();
</script>
</body>
</html>
